(function(root,factory){if(typeof module==="object"&&module.exports){module.exports=factory();}else{root.RyagramScene=factory();}})(typeof self!=="undefined"?self:this,function(){"use strict";var FORMAT="ryagram-scene";var VERSION=1;function pyRound(x){var r=Math.round(x);if(Math.abs(x-Math.trunc(x))===0.5){r=2*Math.round(x/2);}return r;}function intText(v){return String(v);}function four(v){return v.toFixed(4);}function factor(a){var f=Math.trunc(255*a)/255;return Math.max(0,Math.min(1,f));}function composite(inside,opacity,tx,ty){if(!inside){return"";}var attrs="";if(tx||ty){attrs+=' transform="translate('+intText(tx)+","+intText(ty)+')"';}if(opacity<1){attrs+=' opacity="'+four(opacity)+'"';}return attrs?"<g"+attrs+">"+inside+"</g>":inside;}function check(scene){if(!scene||scene.format!==FORMAT){throw new Error("not a ryagram scene");}if(scene.version!==VERSION){throw new Error("scene version "+scene.version+" is not "+VERSION);}}function rleAt(runs,f){var v=0;for(var i=0;i<runs.length;i++){if(runs[i][0]>f){break;}v=runs[i][1];}return v;}function clock(scene,f){var c=scene.clock;var tk=c.ticks[f];var period=c.periods[tk[0]];var t=tk[1];var next=(t>0&&tk[0]+1<c.periods.length)?c.periods[tk[0]+1]:null;return{period:period,next:next,t:t,here:parseInt(period.slice(0,4),10),nxt:next===null?null:parseInt(next.slice(0,4),10),fade:c.reveal_fade[period]};}function mileAlpha(k,n,t,fade){var start=n>1?(k/(n-1))*(1.0-fade):1.0-fade;return Math.max(0.0,Math.min(1.0,(t-start)/fade));}function strength(year,rank,ck){if(year<=ck.here){return 1.0;}if(ck.nxt===null||!(ck.here<year&&year<=ck.nxt)){return 0.0;}return mileAlpha(rank[0],rank[1],ck.t,ck.fade);}function reveal(scene,ck){var r=scene.parts.reveal;if(ck.nxt===null||!(ck.t>0&&ck.t<1)){return"";}var lit=[];for(var y in r.miles){var yr=parseInt(y,10);if(!(ck.here<yr&&yr<=ck.nxt)){continue;}var ms=r.miles[y];for(var i=0;i<ms.length;i++){var a=mileAlpha(ms[i][1],ms[i][2],ck.t,ck.fade);if(a>0){lit.push([a,ms[i][0],ms[i][3]]);}}}lit.sort(function(p,q){if(p[0]!==q[0]){return p[0]<q[0]?-1:1;}return p[1]<q[1]?-1:(p[1]>q[1]?1:0);});var steps={};var order=[];for(var j=0;j<lit.length;j++){var s=pyRound(255*lit[j][0]);if(!(s in steps)){steps[s]=[];order.push(s);}steps[s].push(lit[j][2]);}order.sort(function(p,q){return p-q;});var out="";for(var k=0;k<order.length;k++){var op=1.0*(order[k]/255);out+='<path data-layer="'+r.layer+'"'+(op<1?' opacity="'+four(op)+'"':"")+' d="'+steps[order[k]].join(" ")+'" fill="none" stroke="'+r.stroke+'" stroke-width="'+r.width+'" stroke-linecap="round" stroke-linejoin="round"/>';}return out;}function graphics(scene,f,ck){var p=scene.parts;var out=p.page+p.states;var ctx=p.context;var a=ctx?rleAt(ctx.a,f):0;if(ctx&&a>0){out+=composite(ctx.layer,factor(a*ctx.alpha),0,0);}out+=p.base;for(var i=0;i<p.years.length;i++){if(p.years[i][0]<=ck.here){out+=p.years[i][1];}}out+=reveal(scene,ck);for(var k=0;k<p.shields.length;k++){var sh=p.shields[k];var s=strength(sh.year,sh.rank,ck);if(s<=0){continue;}out+=composite(sh.svg,s<1?factor(s):1,sh.x,sh.y);}return out;}function texts(scene,f,ck){var p=scene.parts;var ctx=p.context;var a=ctx?rleAt(ctx.a,f):0;var out=p.readouts[p.readout_at[f]]+p.key;if(ctx&&a>0){out+=composite(ctx.key,factor(a),0,0);}out+=p.year_labels[ck.period]+p.heading+p.subtitle+p.source;if(ctx&&a>0){out+=composite(ctx.credit,factor(a),0,0);}return out;}function body(scene,frame,opts){check(scene);var f=frame|0;if(f<0||f>=scene.frames){throw new Error("frame "+frame+" is outside 0.."+(scene.frames-1));}var which=(opts&&opts.parts)||"all";var ck=clock(scene,f);if(which==="graphics"){return graphics(scene,f,ck);}if(which==="texts"){return texts(scene,f,ck);}return graphics(scene,f,ck)+texts(scene,f,ck);}function defs(scene){var out="";var ids=Object.keys(scene.defs);for(var i=0;i<ids.length;i++){out+=scene.defs[ids[i]];}return out;}function draw(scene,frame,opts){var w=scene.canvas[0];var h=scene.canvas[1];return'<svg xmlns="http://www.w3.org/2000/svg" width="'+w+'" height="'+h+'" viewBox="0 0 '+w+" "+h+'"><defs>'+defs(scene)+"</defs>"+body(scene,frame,opts)+"</svg>";}function describe(scene,frame){check(scene);var ck=clock(scene,frame|0);return{period:ck.period,readout:scene.parts.readout_values[scene.parts.readout_at[frame|0]]};}return{draw:draw,body:body,describe:describe,FORMAT:FORMAT,VERSION:VERSION};});
